spec.expr:
sum by (project, action) (
  rate(
    {
      __name__=~".*_request_durations_histogram_seconds_count",
      project=~"${services:regex}",
      action=~".+-.+$"
    }[5m]
  )
)

(
  (node_filesystem_size_bytes{instance="$nodeInstance", job="$nodeJob", mountpoint="/", fstype!="rootfs"}
   - node_filesystem_avail_bytes{instance="$nodeInstance", job="$nodeJob", mountpoint="/", fstype!="rootfs"})
  / node_filesystem_size_bytes{instance="$nodeInstance", job="$nodeJob", mountpoint="/", fstype!="rootfs"}
) * 100

histogram_quantile(
    0.95,
    sum by (le, project, action) (
      rate(
        {
          __name__=~".+_request_durations_histogram_seconds_bucket",
          job=~"(${services:regex})-${suffix}",
          action=~".+-.+",
          action!="all"
        }[5m]
      )
    )
  )
